use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200001
    let mut sieve: Vec<bool> = [true; 200001]
    let mut counts: Vec<int> = [0; 200001]
    let mut last: Vec<int> = [0; 200001]
    let mut c = 0
    let mut l = 0
    let mut i = 0
    while i < limit {
        if i < 2 {
            sieve[i] = false
        } else if sieve[i] {
            let mut j = i * i
            while j < limit {
                sieve[j] = false
                j += i
            }
        }
        if sieve[i] {
            c += 1
            l = i
        }
        counts[i] = c
        last[i] = l
        i += 1
    }
    let mut first = true
    let mut out: Vec<string> = []
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        if first {
            first = false
            continue
        }
        let n = t.parse::<int>().unwrap_or(0)
        if counts[n] == 0 {
            out.push("0 none")
        } else {
            out.push("${counts[n]} ${last[n]}")
        }
    }
    println(out.join("\n"))
}

